# 删除华兰疫苗用不到的菜单 by lilong 240304
DELETE FROM bmos_platform.bp_menu WHERE bp_menu.parent_id NOT IN (
'100030001',
'100030002',
'100030003',
'100030004',
'100030005',
'100040001',
'100040002',
'120010001',
'120010002',
'120020010',
'120030008',
'120050003',
'120050004',
'111010001',
'111010002',
'111020003'               )and is_menu = 0;


